        category: .violent,
        headlines: ["Shrimp Boat Crewman Cut in Dock Argument", "First Mate From Trawler Case Back in Court"],
        law: "awdw",
        spec: "Assaulted {V} with a deadly weapon, a knife, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a crewman on another boat was cut on the arm at the dock after a pay dispute. {DL} says {V} swung first.",
