        category: .violent,
        headlines: ["Nursing Home Resident Bruised After Guard Escort", "Security Guard From Hospital Case Faces New Complaint"],
        law: "simpleAssault",
        spec: "Assaulted {V} by striking {V.him}, on {DATE}.",
        ages: 18...60,
        victim: true,
