        state: [E(.forensic, 3, "Medical Report", "Bruises."), E(.statement, 2, "Aide", "{V} named {D}.")],
        defense: [E(.statement, 1, "Fall", "{DL} says {V} fell.")],
        role: "Aide",
        exam: [.direct("What is your job?", "\"I'm a care aide at a residential home, helping residents with meals, medicine, and getting around.\""), .direct("What happened to the resident?", "\"An older resident came back from a walk with bruises on one arm and a sore shoulder, and told me a guard had hurt {V.him}.\""), .direct("Who was the guard?", "\"{DL}, who works nights and sometimes escorts residents up the back stairwell when the elevator is out.\""), .direct("What did {V} tell you?", "\"That {DL} grabbed {V.his} arm hard on the stairs, shoved {V.him} against the wall, and told {V.him} to hurry up.\""), .direct("What did the medical report show?", "\"Bruises on the upper arm in the shape of fingers, and a sore shoulder consistent with a hard grip.\""), .direct("What did {DL} say?", "\"{D.He} said the resident fell on the stairs and that {D.he} only tried to catch {V.him}.\""), .cross("The stairwell has no camera?", "\"Correct, which is why we only have what {V} said and the injuries.\""), .cross("{V} has some memory problems?", "\"A little, but {V.he} was clear about what happened and told it the same way twice.\""), .cross("{DL} reported a fall?", "\"{D.He} didn't write an incident report that night, and I only learned of it from {V}.\""), .cross("Falls do happen in stairwells?", "\"They do, but fingerprint-shaped bruises are not typical of a fall.\""), .cross("{DL} has been a good employee otherwise?", "\"{D.He} had no complaints on file before this.\"")],
        theory: ("{D} hit a resident.", "A fall."),
        allocution: "\"I was escorting that resident down the stairwell, which is part of my job, and the resident fell. I never struck anyone. I'm sorry for the bruises and for how frightening a fall must have been. I'd ask the court to know I take pride in keeping people safe.\"",
        truths: ("{DL} had a prior case in this court.", "The stair light was out."),
        defendant: [.direct("Did you grab the resident?", "\"I grabbed {V.his} arm when {V.he} started to fall on the stairs. I was trying to catch {V.him}.\""), .direct("How did {V} fall?", "\"{V.He} stumbled on a step while I was walking beside {V.him}, and I reached out to steady {V.him}.\""), .direct("Did you shove {V.him} against the wall?", "\"No, {V.he} swung against the wall as {V.he} fell, and I held on so {V.he} wouldn't go down the stairs.\""), .direct("Why didn't you write a report?", "\"I should have. It was a busy night, and I thought no one was hurt, so I put it off.\""), .direct("What did you do when you heard about the bruises?", "\"I told my supervisor what happened and said I was sorry that the grip left marks.\""), .direct("What would you tell the resident?", "\"I'm sorry for hurting you. I only wanted to keep you from falling, and I should have been gentler.\""), .cross("You've been accused of rough treatment of a resident before, weren't you?", "\"Yes, and I was told to be careful. I was careful, but I know it looks bad.\""), .cross("Bruises in the shape of fingers come from a hard grip, don't they?", "\"They can, and I did hold on hard. I thought the alternative was worse.\""), .cross("You failed to file an incident report?", "\"I did, and I regret it, because a report would have protected both of us.\""), .cross("You'll complete training on moving residents?", "\"Yes, any course the facility or the court requires.\""), .cross("You'll file reports for every incident?", "\"Yes, immediately, even if I think it's minor.\"")],
        openings: ("A care aide at a residential home saw an older resident return from a walk with bruises on one arm and a sore shoulder, and the resident said guard {D} had hurt {V.him} in the stairwell, and the medical report shows bruises, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say {V} fell on the stairs and {D} caught {V.him}, and the bruises came from the fall. {D} did not strike a resident."),
        closings: ("The medical report shows bruises on {V}'s arm and shoulder, {V} named {D} to the aide, and with {PRIOR} behind {D.him}, {DL} knew what an escort on a stairwell requires.", "A fall on stairs leaves bruises, and {V} did not see a blow struck by anyone. The State must prove {D} hit {V} and that the bruises did not come from the fall."),
        timeline: [(0, "11 p.m.: escort."), (0, "11:20 p.m.: found.")],
        identified: "A report.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction)

    static let dialysisAgain = SmallCases.make(
        key: "story.followup.dialysisAgain",
        category: .violent,
        headlines: ["Pharmacy Staff Threatened in Letter After Refill Dispute", "Author of Clinic Threat Note Writes Again"],
